def feature(s):
    s = s or {}
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = (s.get('basic_structure_statistics') or {}).get('volume_per_atom_A3')
    if v is None:
        sites = s.get('sites') or []
        volume = (s.get('lattice') or {}).get('volume_A3')
        v = volume / len(sites) if volume and sites else 0.0
    return log(v) if v and v > 0 else 0.0

def feature(s):
    s = s or {}
    props = s.get('element_properties') or {}
    comp = s.get('composition') or {}
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = (s.get('basic_structure_statistics') or {}).get('volume_per_atom_A3')
    if not v or v <= 0:
        return 0.0
    numerator = 0.0
    weight = 0.0
    for element, fraction in comp.items():
        r = (props.get(element) or {}).get('covalent_radius_A')
        if r is not None and r > 0 and fraction is not None and fraction > 0:
            numerator += fraction * r * r * r
            weight += fraction
    return 4.0 * pi * numerator / (3.0 * v * weight) if weight else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') for a in sites]
    nearest = [inf] * n
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0:
                nearest[i] = min(nearest[i], d / (a + b))
    values = [x for x in nearest if isfinite(x)]
    return sum(values) / len(values) if values else 0.0

