def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    edges = s.get('neighbors') or []
    n = len(sites)
    en = [(props.get(a.get('element')) or {}).get('eneg') for a in sites]
    nearest = [inf] * n
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0:
            nearest[i] = min(nearest[i], d)
    counts = [0.0] * n
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 1.25 * nearest[i]:
            o = sites[j].get('occupancy')
            counts[i] += max(0.0, o) if o is not None else 1.0
    valid = [i for i in range(n) if en[i] is not None and isfinite(nearest[i])]
    if not valid:
        return 0.0
    a = sum(en[i] for i in valid) / len(valid)
    b = sum(counts[i] for i in valid) / len(valid)
    return sum((en[i] - a) * (counts[i] - b) for i in valid) / len(valid)

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    if not n:
        return 0.0
    radii = []
    eligible = []
    occupancy = []
    for site in sites:
        element = site.get('element')
        p = props.get(element) or {}
        radii.append(p.get('covalent_radius_A'))
        group = p.get('group')
        en = p.get('eneg')
        eligible.append(element == 'H' or (group is not None and 14 <= group <= 17 and en is not None and en >= 2.0))
        o = site.get('occupancy')
        occupancy.append(max(0.0, o) if o is not None else 1.0)
    total = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0:
            if eligible[i] and sites[i].get('element') == sites[j].get('element'):
                a = radii[i]
                b = radii[j]
                if a is not None and b is not None and a > 0 and b > 0 and d <= 1.2 * (a + b):
                    total += occupancy[i] * occupancy[j]
    population = sum(occupancy)
    return 0.5 * total / population if population else 0.0

