def feature(s):
    s = s or {}
    props = s.get('element_properties') or {}
    total = 0.0
    weight = 0.0
    for element, fraction in (s.get('composition') or {}).items():
        p = props.get(element) or {}
        ion = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if ion is not None and affinity is not None and fraction is not None and fraction > 0:
            total += fraction * (ion - affinity)
            weight += fraction
    return total / weight if weight else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    edges = s.get('neighbors') or []
    n = len(sites)
    if not n:
        return 0.0
    chi = []
    hardness = []
    occupancy = []
    for site in sites:
        p = props.get(site.get('element')) or {}
        ion = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if ion is not None and affinity is not None:
            chi.append(0.5 * (ion + affinity))
            hardness.append(max(0.5, ion - affinity))
        else:
            chi.append(None)
            hardness.append(None)
        o = site.get('occupancy')
        occupancy.append(max(0.0, o) if o is not None else 1.0)
    nearest = [inf] * n
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0:
            nearest[i] = min(nearest[i], d)
    total = 0.0
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 1.25 * nearest[i]:
            if chi[i] is not None and chi[j] is not None:
                total += occupancy[i] * occupancy[j] * (chi[i] - chi[j]) ** 2 / (hardness[i] + hardness[j])
    population = sum(occupancy)
    return 0.5 * total / population if population else 0.0

def feature(s):
    s = s or {}
    props = s.get('element_properties') or {}
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = (s.get('basic_structure_statistics') or {}).get('volume_per_atom_A3')
    if v is None or v <= 0:
        return 0.0
    total = 0.0
    weight = 0.0
    for element, fraction in (s.get('composition') or {}).items():
        valence = (props.get(element) or {}).get('valence_electrons')
        if valence is not None and fraction is not None and fraction > 0:
            total += fraction * valence
            weight += fraction
    return total / (weight * v) if weight else 0.0
